import java.util.*;
public class InvB {
 private ArrayList<String> list;

 public InvB() {
   list = new ArrayList<String>();
 }


 public void abc(String s) {
   list.add(s);
 }


 public String xyz() {
   return list.remove(0);
 }


 public String mno() {
   return list.get(0);
 }


 public boolean efg() {
   return list.size() == 0;
 }
 public static void main(String[] args) {
 InvB obj = new InvB();
 obj.abc("dog");obj.abc("cat");
 obj.abc("bird");obj.abc("turtle");
 obj.abc("pig");obj.abc("rat");
 obj.mno();obj.xyz();obj.abc("dog");
 obj.abc(obj.mno());
 while(!obj.efg())
   System.out.print(obj.xyz() + " ");
 }
}

